#include "StdAfx.h"#include "CinematicCameraPlugin.h"#include "CinematicCameraComponent.h"#include "HDRIImport.h"#include <CrySchematyc/Env/IEnvRegistry.h>#include <CrySchematyc/Env/EnvPackage.h>#include <CrySchematyc/Utils/SharedString.h>#include <CryCore/StaticInstanceList.h>#include <CryCore/Platform/platform_impl.inl>#include <CrySystem/IConsole.h>#include <CrySystem/ConsoleRegistration.h>// ccam_slot <1-9>: make the cinematic camera carrying that Camera Slot the active one. Bind it// to keys ("bind 1 ccam_slot 1") to cut between cameras; a Phone Tracker set to follow the// active camera moves along.static void CmdCcamSlot(IConsoleCmdArgs* pArgs){	if (pArgs->GetArgCount() < 2)	{		CryLogAlways("ccam_slot <1-9>: activate the cinematic camera with that Camera Slot");		return;	}	const int slot = atoi(pArgs->GetArg(1));	if (CCinematicCameraComponent* pCamera = CCinematicCameraComponent::FindBySlot(slot))	{		pCamera->Activate();		CryLogAlways("[CinematicCamera] slot %d -> '%s'", slot, pCamera->GetEntity()->GetName());	}	else	{		CryLogAlways("[CinematicCamera] no cinematic camera has Camera Slot %d", slot);	}}CCinematicCameraPlugin::~CCinematicCameraPlugin(){	if (gEnv->pConsole)		gEnv->pConsole->RemoveCommand("ccam_slot");	RemoveHDRIImportCommands();	gEnv->pSystem->GetISystemEventDispatcher()->RemoveListener(this);	if (gEnv->pSchematyc)		gEnv->pSchematyc->GetEnvRegistry().DeregisterPackage(CCinematicCameraPlugin::GetCID());}bool CCinematicCameraPlugin::Initialize(SSystemGlobalEnvironment& env, const SSystemInitParams& initParams){	gEnv->pSystem->GetISystemEventDispatcher()->RegisterListener(this, "CCinematicCameraPlugin");	// Register for the UpdateBeforeFinalizeCamera hook so we can apply EV compensation	// after the TOD system sets E3DPARAM_HDR_EYEADAPTATION_PARAMS.	EnableUpdate(EUpdateStep::BeforeFinalizeCamera, true);	REGISTER_COMMAND("ccam_slot", CmdCcamSlot, VF_NULL, "ccam_slot <1-9>: activate the cinematic camera with that Camera Slot");	// rec_ImportHDRI - the HDRI to environment-probe importer (HDRIImport.cpp).	RegisterHDRIImportCommands();	return true;}void CCinematicCameraPlugin::UpdateBeforeFinalizeCamera(){	// Resolve ownership from the camera manager FIRST: it is the single authority, and this	// is also where a dethroned cinematic camera hands the render state back. Returns nullptr	// when a non-cinematic camera is active, in which case we finalize nothing.	// Nothing is finalized while a level is loading: FinalizeGameCamera() writes the view camera	// and ApplyExposureGlobalParam() writes E3DPARAM_HDR_EYEADAPTATION_PARAMS, and both belong to	// a level that exists. Same gate as CanDriveRenderState(), asked one level up so the resolver	// does not hand the render state around mid-load either.	if (!CCinematicCameraComponent::IsLevelReady())		return;	if (CCinematicCameraComponent* pActive = CCinematicCameraComponent::ResolveActive())	{		pActive->FinalizeGameCamera();		pActive->ApplyExposureGlobalParam();		// Per frame, in editor and game alike, so a ResetPostEffects (level load / RESET) cannot		// leave the shafts stage on under an active camera.		pActive->ApplySunShaftsOff();	}}void CCinematicCameraPlugin::OnSystemEvent(ESystemEvent event, UINT_PTR wparam, UINT_PTR lparam){	switch (event)	{	case ESYSTEM_EVENT_REGISTER_SCHEMATYC_ENV:	{		auto staticAutoRegisterLambda = [](Schematyc::IEnvRegistrar& registrar)		{			Detail::CStaticAutoRegistrar<Schematyc::IEnvRegistrar&>::InvokeStaticCallbacks(registrar);		};		if (gEnv->pSchematyc)		{			gEnv->pSchematyc->GetEnvRegistry().RegisterPackage(				stl::make_unique<Schematyc::CEnvPackage>(					CCinematicCameraPlugin::GetCID(),					"CinematicCameraComponents",					"CryEngine",					"Cinematic Camera Components",					staticAutoRegisterLambda));		}		break;	}	// Level lifetime (2026-09-07). The cinematic camera drives shared render state - the	// post-effect bus, two uploaded 3D LUT textures, the engine-side light-unit convention and,	// through it, a forced time-of-day and sky-dome recompute. None of that may happen while a	// level is being torn down or built: the targets, the bus and the time of day all belong to	// the level. CCinematicCameraComponent::CanDriveRenderState() already refuses for the	// duration (it asks ESYSTEM_GLOBAL_STATE), so these two hooks only have to bracket it -	// release what we own while it is still ours, and forget what we cached once the level is up.	case ESYSTEM_EVENT_LEVEL_UNLOAD_START:	case ESYSTEM_EVENT_LEVEL_UNLOAD:	case ESYSTEM_EVENT_LEVEL_POST_UNLOAD:	case ESYSTEM_EVENT_LEVEL_LOAD_PREPARE:	case ESYSTEM_EVENT_LEVEL_LOAD_START:		CCinematicCameraComponent::OnLevelTeardown();		break;	case ESYSTEM_EVENT_LEVEL_LOAD_END:	case ESYSTEM_EVENT_LEVEL_GAMEPLAY_START:		CCinematicCameraComponent::OnLevelLoaded();		break;	default:		break;	}}CRYREGISTER_SINGLETON_CLASS(CCinematicCameraPlugin)// ---------------------------------------------------------------------------// C entry point used by other plugins (CryPhoneTracker) to drive the lens without// linking against this module. See Interface/ICinematicCameraOptics.h.// ---------------------------------------------------------------------------extern "C" DLL_EXPORT ICinematicCameraOptics* CryGetCinematicCameraOptics(IEntity* pEntity){	if (pEntity == nullptr)		return nullptr;	return pEntity->GetComponent<CCinematicCameraComponent>();}// Entity of the active cinematic camera, so a controller can follow camera switches.extern "C" DLL_EXPORT IEntity* CryGetActiveCinematicCameraEntity(){	CCinematicCameraComponent* pActive = CCinematicCameraComponent::GetActiveComponent();	return pActive ? pActive->GetEntity() : nullptr;}extern "C" DLL_EXPORT bool CryActivateCinematicCameraSlot(int slot){	if (CCinematicCameraComponent* pCamera = CCinematicCameraComponent::FindBySlot(slot))	{		pCamera->Activate();		return true;	}	return false;}